!function(){"use strict";const t=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const a=e.target.dataset.aosDelay;a?setTimeout(()=>{e.target.classList.add("aos-animate")},parseInt(a,10)):e.target.classList.add("aos-animate"),t.unobserve(e.target)}})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll("[data-aos]").forEach(e=>{t.observe(e)})}();